/** Layered feature configuration: definition, deployment environment, then account. */
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype;
export function resolveFeatureFlags(definitions, environment = {}, user = {}) {
  if (![definitions, environment, user].every(plain)) throw new TypeError('flag maps must be plain objects');
  const result = {};
  for (const [name, value] of Object.entries(definitions)) {
    if (typeof value !== 'boolean') throw new TypeError('definition must be boolean');
    Object.defineProperty(result, name, { value, enumerable: true, writable: true, configurable: true });
  }
  for (const layer of [environment, user]) {
    for (const [name, value] of Object.entries(layer)) {
      if (Object.hasOwn(result, name) && typeof value === 'boolean') result[name] = value;
    }
  }
  return result;
}
